  $svmkjson${"slug": "services-marketing", "title": "Services Marketing", "description": "Frame services as experiences, performances, relationships, and systems that require different marketing logic than tangible goods.", "topics": [{"id": "cd6b658e-543a-425b-b31b-279074ea005e", "type": "topic", "title": "Services Marketing Foundations and the Service-Dominant Economy", "description": "Frame services as experiences, performances, relationships, and systems that require different marketing logic than tangible goods.", "children": [{"id": "a063ca97-baaa-462f-bcdc-bc9a8e1e5f0e", "type": "subtopic", "title": "Why Services Need Distinct Marketing", "children": [{"id": "52a04915-60b3-4b03-9c1a-f085df3ea576", "type": "concept", "title": "Service economy, experience economy, service-dominant logic, value-in-use, and co-creation"}, {"id": "29847315-306a-458c-ad34-91faf30b956c", "type": "concept", "title": "Services as performances, processes, promises, and relationships"}, {"id": "f88fb4bb-7cfa-4c57-ae7c-9efeb3e1dd92", "type": "concept", "title": "Implications for positioning, delivery, measurement, and loyalty"}], "description": "Services are often bought before they can be fully evaluated, which makes trust, evidence, relationships, and experience design central."}, {"id": "a8f4c51a-8a52-4986-be41-beaaaf8ad5cb", "type": "subtopic", "title": "Service Strategy and the Marketing Mix", "children": [{"id": "1cbe2eec-1385-41aa-9716-6c46d1891302", "type": "concept", "title": "7Ps: product, price, place, promotion, people, process, and physical evidence"}, {"id": "1d91a4d1-716f-4eb0-99e1-94ee00e2ce7f", "type": "concept", "title": "Service concept, value proposition, target segment, and competitive advantage"}, {"id": "54004e87-673c-4d44-9c07-e305a85acf83", "type": "concept", "title": "Service standards, brand promise, and delivery capability"}], "description": "Students learn how the classic marketing mix expands when the offering is performed through people, process, and evidence."}, {"id": "d23aa913-5f99-4047-9911-7c04a17a3336", "type": "subtopic", "title": "Service Categories and Business Models", "children": [{"id": "010693d1-7c86-40e6-a019-fd29fc5e8a05", "type": "concept", "title": "B2C, B2B, professional, hospitality, retail, healthcare, financial, subscription, and platform services"}, {"id": "d2f3307c-d9a2-4af8-b11c-3da8c1fcf9c3", "type": "concept", "title": "High-contact versus low-contact services"}, {"id": "95d5a4e5-58d8-4054-ac7a-9f2607c5e646", "type": "concept", "title": "Membership, recurring revenue, freemium, marketplace, and usage-based models"}], "description": "Services differ by customer contact, customization, risk, duration, expertise, and delivery channel."}]}, {"id": "f499093d-c580-4fba-ad91-3ddfe78d7946", "type": "topic", "title": "Services vs. Goods, IHIP Characteristics, and Customer Participation", "description": "Analyze intangibility, heterogeneity, inseparability, perishability, ownership, and co-production as core service-marketing challenges.", "children": [{"id": "94c04dc4-b3a2-4033-a60d-28e1d298f9bb", "type": "subtopic", "title": "IHIP Characteristics", "children": [{"id": "3f9a7d52-ddc0-46c7-aeb9-1f68cb5c3401", "type": "concept", "title": "Intangibility, heterogeneity, inseparability, and perishability"}, {"id": "6ec26362-55ec-4043-92f8-a8779d1d6735", "type": "concept", "title": "Ownership, simultaneity, variability, and performance risk"}, {"id": "024b85c3-9719-4741-9a54-186ea139e246", "type": "concept", "title": "How IHIP affects communication, pricing, quality control, and operations"}], "description": "The IHIP framework helps explain why services are harder to evaluate, standardize, store, and separate from delivery."}, {"id": "1e0d9391-3dd6-472b-ae68-8827a8cff83b", "type": "subtopic", "title": "Customer Participation and Co-Production", "children": [{"id": "b370e5dc-173e-4e8b-90d8-ef319b9544f1", "type": "concept", "title": "Customer roles, scripts, responsibilities, readiness, and onboarding"}, {"id": "8a3eb81c-70b4-46d4-a1bf-d792394cd304", "type": "concept", "title": "Co-production, co-creation, self-service, and customer education"}, {"id": "ed2d9767-77c3-4d35-b0bf-499b0107a88f", "type": "concept", "title": "Managing customer error, anxiety, and participation burden"}], "description": "Customers often help produce the service, so their behavior affects quality, cost, and outcomes."}, {"id": "5b697866-c6e7-4f59-ab1c-589a24226008", "type": "subtopic", "title": "Risk and Trust in Service Evaluation", "children": [{"id": "848b0b87-a083-4076-8b2d-37146c6bff62", "type": "concept", "title": "Search, experience, and credence attributes"}, {"id": "9c2c9d0b-b731-43fc-9bdc-de6d441dd09c", "type": "concept", "title": "Perceived risk, trust, guarantees, reviews, referrals, and reputation"}, {"id": "d9e414c7-05ea-4bb0-8d37-74557742fcb2", "type": "concept", "title": "Reducing uncertainty through proof, transparency, and trials"}], "description": "Services can be difficult to judge before purchase, so customers use signals and relationships to reduce risk."}]}, {"id": "b4e4fd16-5cfe-4a59-a133-d0b05a4d163a", "type": "topic", "title": "Customer Expectations, Perceptions, and Service Quality", "description": "Understand how customers form expectations, evaluate service encounters, and judge quality before, during, and after consumption.", "children": [{"id": "b81636e3-73a9-48b6-b2cb-e5d4eba22411", "type": "subtopic", "title": "Expectation Formation", "children": [{"id": "04ec7ead-fc49-4323-9c51-c0f2b3fa1438", "type": "concept", "title": "Desired service, adequate service, predicted service, and zone of tolerance"}, {"id": "37a2af3b-787d-4113-b50d-83b8d0817d15", "type": "concept", "title": "Word of mouth, prior experience, advertising, price, reviews, and situational factors"}, {"id": "28270ec9-4db0-42b2-8cb6-e738dfc3fe68", "type": "concept", "title": "Managing promises without overpromising"}], "description": "Customers compare performance against expected, desired, and adequate service levels."}, {"id": "d026499e-6ba5-4e6b-8876-57441cb9f49f", "type": "subtopic", "title": "Perceived Service Quality", "children": [{"id": "307b3012-5da6-4fed-b66c-04ab214458cb", "type": "concept", "title": "Technical quality, functional quality, interaction quality, and outcome quality"}, {"id": "598463e9-9558-4c64-9d69-37e49da63df4", "type": "concept", "title": "Reliability, responsiveness, assurance, empathy, and tangibles"}, {"id": "c50fb10f-9a68-4225-bbfe-8c884a836e3e", "type": "concept", "title": "Moments of truth and cumulative experience"}], "description": "Quality is judged through the customer's perception of both outcome and process."}, {"id": "0b15dd39-2fa9-403c-81f5-fd5ea0126905", "type": "subtopic", "title": "Satisfaction, Delight, and Loyalty", "children": [{"id": "f7c19b7b-256d-4408-a377-991bb72ffa1e", "type": "concept", "title": "Satisfaction, dissatisfaction, delight, trust, commitment, and advocacy"}, {"id": "2aa78965-d413-4203-81e4-5873d903dc90", "type": "concept", "title": "Post-purchase evaluation, confirmation/disconfirmation, and emotional memory"}, {"id": "b3bb2732-6044-4c31-b2c8-e0eaeb4da941", "type": "concept", "title": "Retention, churn, referral, and share of wallet"}], "description": "Satisfaction is not the same as loyalty, but it strongly shapes retention, advocacy, and repeat use."}]}, {"id": "c3d731e2-4dea-45e3-b1a8-b8e4d3ed6ce1", "type": "topic", "title": "SERVQUAL, Gaps Model, and Voice-of-Customer Measurement", "description": "Use service-quality frameworks and feedback systems to diagnose failures and prioritize improvement.", "children": [{"id": "2ee1c74f-7586-4f01-bb84-6045fbb59929", "type": "subtopic", "title": "SERVQUAL and Service Quality Dimensions", "children": [{"id": "90880d2c-4767-494b-b945-d0f2436512da", "type": "concept", "title": "Reliability, responsiveness, assurance, empathy, and tangibles"}, {"id": "0fbedb2c-a9c3-4b8c-a486-e9225bf62580", "type": "concept", "title": "Expectation-perception gaps, scale construction, and interpretation"}, {"id": "331e57d2-ee33-454b-b550-50d37b1602d5", "type": "concept", "title": "Strengths, limits, and alternatives to SERVQUAL"}], "description": "SERVQUAL gives students a structured way to measure service expectations and perceptions."}, {"id": "884438e1-dc55-4762-90ad-530e273a04f3", "type": "subtopic", "title": "Gaps Model Diagnosis", "children": [{"id": "dcd7f2d0-0ba7-44b3-b756-0790238c315f", "type": "concept", "title": "Knowledge gap, standards gap, delivery gap, communication gap, and customer gap"}, {"id": "99764b43-22fd-4419-828b-50cf85c3ceac", "type": "concept", "title": "Customer research, service standards, training, operations, and external promises"}, {"id": "caf2afed-379f-42be-9d61-5d1ca7c66616", "type": "concept", "title": "Prioritizing fixes by root cause and impact"}], "description": "The gaps model helps connect customer dissatisfaction to organizational causes."}, {"id": "995a3ac9-316c-4acc-b7f3-7e1a16d4d809", "type": "subtopic", "title": "Voice of Customer Systems", "children": [{"id": "ae8d42b2-4363-4f8c-b7f4-57dc4d9c230b", "type": "concept", "title": "Transactional surveys, relationship surveys, NPS, CSAT, CES, reviews, complaints, and social listening"}, {"id": "97a3c56d-a3e2-4319-bea8-3b92fb01500c", "type": "concept", "title": "Closed-loop feedback, text analytics, dashboards, and escalation"}, {"id": "fa301106-ff30-4821-b8f9-76c55dc6829b", "type": "concept", "title": "Sampling bias, survey fatigue, and feedback representativeness"}], "description": "Modern service firms need continuous listening systems, not one-off surveys."}]}, {"id": "8e0be73e-87b8-4653-a736-fb332faa2bd9", "type": "topic", "title": "Service Design, Customer Journey Mapping, and Blueprinting", "description": "Translate customer insight into designed experiences, touchpoints, backstage systems, and operational requirements.", "children": [{"id": "64a54dae-e49a-4d61-b505-330f3670a941", "type": "subtopic", "title": "Journey Mapping", "children": [{"id": "39834eea-1a90-48ba-9244-d57a690aba47", "type": "concept", "title": "Stages, goals, emotions, pain points, channels, touchpoints, and moments that matter"}, {"id": "4dd331d3-402c-4809-ac39-f164c8168e12", "type": "concept", "title": "Current-state and future-state journey maps"}, {"id": "720e778a-df61-40c9-83bd-e37afaef06f5", "type": "concept", "title": "Journey evidence from interviews, observation, analytics, and feedback"}], "description": "Journey maps help teams see the customer's end-to-end experience across stages and touchpoints."}, {"id": "57b708ea-608b-4d6f-b59d-b7b1d30e0304", "type": "subtopic", "title": "Service Blueprinting", "children": [{"id": "4c4816f4-a13f-4f6a-9dee-e317178d7869", "type": "concept", "title": "Customer actions, frontstage, backstage, support processes, line of interaction, and line of visibility"}, {"id": "ae36feb8-3238-4487-a297-8ec47d322d5b", "type": "concept", "title": "Failure points, handoffs, wait states, and operational dependencies"}, {"id": "a55bff3f-cb35-4ae7-9e8c-455204a7b0b3", "type": "concept", "title": "Blueprints as design, training, and improvement tools"}], "description": "Blueprints connect customer experience to frontline actions, backstage work, systems, and support processes."}, {"id": "e740ce3e-f376-4373-88ad-f84bd1c2d89b", "type": "subtopic", "title": "Prototyping and Service Innovation", "children": [{"id": "ed868d50-00e2-4b5a-90f8-47d3c1294c55", "type": "concept", "title": "Experience prototypes, role play, service scripts, pilots, concierge tests, and minimum viable services"}, {"id": "91a30852-716b-4ca7-9b86-7178a60c03aa", "type": "concept", "title": "Concept testing, usability testing, and experience labs"}, {"id": "ed207c75-b5ca-49a3-a2fb-7254f530edae", "type": "concept", "title": "Iteration from insight to operating model"}], "description": "Service ideas can be tested before full rollout through prototypes and pilots."}]}, {"id": "594c3953-c805-496e-a04e-3513b10a91e7", "type": "topic", "title": "Service Encounters, People, Culture, and Internal Marketing", "description": "Study frontline employees, service culture, emotional labor, empowerment, and internal alignment as part of the marketing system.", "children": [{"id": "b87f2bac-de02-4d5f-94e8-592cc453c68c", "type": "subtopic", "title": "Frontline Service Encounters", "children": [{"id": "c8405d2c-cf93-467b-a088-5159d0c12948", "type": "concept", "title": "Moments of truth, service scripts, empathy, responsiveness, problem solving, and rapport"}, {"id": "81956b9f-6d54-49be-93e9-8b52d43726d3", "type": "concept", "title": "Customer-contact employees and boundary-spanning roles"}, {"id": "63dd13d9-385f-4d72-a4db-cda67b344dec", "type": "concept", "title": "Consistency without robotic delivery"}], "description": "The service encounter is where brand promises become real for customers."}, {"id": "7fbd80e9-2f63-4856-8769-5f648c8eae4f", "type": "subtopic", "title": "Service Culture and Internal Marketing", "children": [{"id": "7372add1-afd6-48f1-8c7e-19ea207c3819", "type": "concept", "title": "Internal marketing, employer brand, service vision, training, communication, and recognition"}, {"id": "ae0c321b-6b62-4924-af76-21e1dde91359", "type": "concept", "title": "Empowerment, psychological safety, leadership, and role clarity"}, {"id": "4af1d0c1-5de5-4ba4-b4c7-0deac6f87dd7", "type": "concept", "title": "Aligning incentives with customer experience"}], "description": "Employees deliver better service when the organization markets the promise internally as well as externally."}, {"id": "158a01a9-a168-4a71-aedf-dd792558b80a", "type": "subtopic", "title": "Emotional Labor and Employee Experience", "children": [{"id": "f9b215a8-4fe1-4136-85eb-771c12cafdf0", "type": "concept", "title": "Emotional labor, burnout, conflict, difficult customers, and service climate"}, {"id": "ecfacd89-1f55-459c-8e6d-13ed2eeab0f3", "type": "concept", "title": "Employee experience, engagement, staffing, and retention"}, {"id": "5f70f6d3-4f12-49b6-afcc-e8bde5e9d5f1", "type": "concept", "title": "Linking EX, CX, productivity, and service quality"}], "description": "World-class service requires caring for the people who perform care, expertise, hospitality, or support."}]}, {"id": "621db7fd-5602-440e-9334-3d1923229da0", "type": "topic", "title": "Physical Evidence, Servicescapes, Atmospherics, and Digital Interfaces", "description": "Examine how tangible cues, spaces, interfaces, and sensory evidence make intangible services understandable and trustworthy.", "children": [{"id": "a242f18b-e2df-4f01-bdbf-583f177310d5", "type": "subtopic", "title": "Physical Evidence and Tangible Cues", "children": [{"id": "62f77db8-9caa-4523-848e-07fa3a3b5d50", "type": "concept", "title": "Signage, uniforms, equipment, documents, packaging, cleanliness, certifications, and visible process cues"}, {"id": "a9680931-17ab-4f09-baef-8fd53ad18609", "type": "concept", "title": "Risk reduction, brand meaning, and quality signaling"}, {"id": "8976f737-64a2-4cd0-a10b-4613a34817ba", "type": "concept", "title": "Managing evidence across high- and low-contact services"}], "description": "Customers use tangible signals to judge intangible services before and during consumption."}, {"id": "178f1030-ab48-4a90-9bf8-d23ec72fe59f", "type": "subtopic", "title": "Servicescapes and Atmospherics", "children": [{"id": "3c835179-27db-459a-9b5e-9175bffc6013", "type": "concept", "title": "Ambient conditions, layout, spatial flow, symbols, artifacts, scent, lighting, sound, and crowding"}, {"id": "20ea0171-3fa1-453e-920e-72c1302d120e", "type": "concept", "title": "Retail, hospitality, healthcare, banking, and professional-service environments"}, {"id": "262ae921-1c53-4a91-9f6d-51f2f8ba0f34", "type": "concept", "title": "Accessibility, inclusion, safety, and sensory design"}], "description": "The service environment shapes emotion, behavior, trust, dwell time, and perceived quality."}, {"id": "eccbc21f-703d-4dcd-8ae2-5825486cd2b4", "type": "subtopic", "title": "Digital Interfaces as Servicescapes", "children": [{"id": "7478ff86-ef3d-42cc-a97f-b54b6c57399c", "type": "concept", "title": "UX, usability, information architecture, microcopy, onboarding, and error states"}, {"id": "22ebcd19-3b5d-43c4-9f34-2c7a9da94329", "type": "concept", "title": "Self-service portals, mobile apps, chatbots, and omnichannel consistency"}, {"id": "67023f6d-f831-4805-a466-aad669143847", "type": "concept", "title": "Trust cues, security cues, and digital accessibility"}], "description": "Websites, apps, kiosks, and chat interfaces are modern service environments."}]}, {"id": "108a4ca9-071b-4569-bef1-90cbdcf0efa6", "type": "topic", "title": "Service Recovery, Complaint Management, and Customer Trust", "description": "Learn how firms respond to failure, rebuild trust, and turn breakdowns into learning and loyalty opportunities.", "children": [{"id": "31237cd4-dc86-4651-8906-fd2b8283cc21", "type": "subtopic", "title": "Service Failure Types", "children": [{"id": "4e1bf243-bc69-41db-8d9f-54bfdc970649", "type": "concept", "title": "Core service failure, process failure, interaction failure, policy failure, and outcome failure"}, {"id": "6fc61209-331a-43bd-88a2-dde5c66939cc", "type": "concept", "title": "Severity, controllability, recurrence, and customer vulnerability"}, {"id": "133a0e64-6686-4193-bca5-80855f2a69bb", "type": "concept", "title": "Detecting failures before complaints appear"}], "description": "Different failures require different recovery strategies and communication."}, {"id": "b26d4339-c9be-46b2-aa83-aa1f8d988bda", "type": "subtopic", "title": "Recovery Strategy", "children": [{"id": "7c4a076a-260a-4173-afb1-3074e2e4c803", "type": "concept", "title": "Apology, explanation, speed, empathy, compensation, correction, and follow-up"}, {"id": "98b03b46-a661-42c1-8a11-f97cc10d9ed3", "type": "concept", "title": "Procedural, interactional, and distributive justice"}, {"id": "71150cfc-036c-44fd-9a9c-bf54791c57db", "type": "concept", "title": "Service guarantees and recovery empowerment"}], "description": "Recovery restores fairness, confidence, and relationship value after a breakdown."}, {"id": "3f25039e-41a1-4c25-9f1d-2038b8206c83", "type": "subtopic", "title": "Complaint Learning and Trust Repair", "children": [{"id": "5b825420-87ca-4ae3-9cb2-f7f1f495865a", "type": "concept", "title": "Complaint channels, escalation, root-cause analysis, closed-loop learning, and prevention"}, {"id": "bb9a38b5-7caf-431f-87eb-5e6cc946f112", "type": "concept", "title": "Trust, forgiveness, switching, negative word of mouth, and recovery paradox"}, {"id": "9d02edcb-6b42-45d9-a56f-be6ef2cb2b4c", "type": "concept", "title": "When recovery can and cannot create loyalty"}], "description": "Complaints are not only costs; they are high-value data about system weakness."}]}, {"id": "0f5b6177-b38f-49bc-91cf-11baeb1a5580", "type": "topic", "title": "Service Pricing, Revenue Management, and Value Communication", "description": "Apply pricing logic to intangible, time-sensitive, capacity-constrained, and relationship-based services.", "children": [{"id": "ef2c7213-1c22-4316-a347-cc75257cafec", "type": "subtopic", "title": "Pricing Intangible Value", "children": [{"id": "8d5938da-64fe-41ec-b807-2c41e52683ec", "type": "concept", "title": "Value-based pricing, cost-based pricing, competition-based pricing, and outcome-based pricing"}, {"id": "699589db-0cac-42d7-86f9-57c62d731250", "type": "concept", "title": "Hourly, subscription, retainer, freemium, usage-based, and bundled pricing"}, {"id": "e6d560ce-c819-47ea-bc5f-34111f1f87b0", "type": "concept", "title": "Communicating expertise, convenience, reliability, and peace of mind"}], "description": "Service pricing must communicate value for outcomes that may be uncertain, delayed, or co-produced."}, {"id": "d51fc4de-773a-4ee5-9325-a13d16c67e78", "type": "subtopic", "title": "Revenue and Yield Management", "children": [{"id": "92c556e2-efcb-4d39-9055-064ed59e5249", "type": "concept", "title": "Yield management, revenue management, dynamic pricing, peak/off-peak pricing, and load factors"}, {"id": "9e219d38-89db-478d-99d4-4c0fd92a7339", "type": "concept", "title": "Hotels, airlines, restaurants, events, ride-share, and appointment services"}, {"id": "588d26a8-1000-4570-a9d4-2d7bfcf2524a", "type": "concept", "title": "Fairness perceptions and transparency"}], "description": "Capacity-constrained services often need dynamic pricing to balance demand and profitability."}, {"id": "759d0825-9e49-41eb-abb6-e1b6f3ef3713", "type": "subtopic", "title": "Price Fairness and Behavioral Response", "children": [{"id": "6c5606a1-9b56-477f-b851-ad4a88700b56", "type": "concept", "title": "Reference price, fairness, partitioned pricing, fees, discounts, tipping, and subscriptions"}, {"id": "69328e14-5426-4205-86ab-e5d499acc12b", "type": "concept", "title": "Willingness to pay, price sensitivity, and perceived sacrifice"}, {"id": "5c42b4f9-2ae6-4ec6-9a55-679eaa6596c7", "type": "concept", "title": "Avoiding hidden-fee backlash and trust erosion"}], "description": "Customers react not only to price level but also to the perceived fairness of rules and fees."}]}, {"id": "8228cfc2-a3aa-4a61-bcba-f82e19db8763", "type": "topic", "title": "Demand, Capacity, Queues, and Wait-Time Experience Design", "description": "Manage demand and capacity while designing fair, transparent, and emotionally intelligent waiting experiences.", "children": [{"id": "28f7b675-c13c-428b-9d46-cc58afcbad76", "type": "subtopic", "title": "Demand and Capacity Management", "children": [{"id": "ab5da271-f3be-47f9-9534-d9785162ed53", "type": "concept", "title": "Perishability, capacity utilization, reservations, appointments, staffing, and demand smoothing"}, {"id": "dc8300b1-5e2a-4ff8-a515-4c0dec2cd523", "type": "concept", "title": "Peak demand, idle capacity, seasonality, and no-shows"}, {"id": "4db247f6-0f58-41a0-8efc-d092d876f3db", "type": "concept", "title": "Matching demand with labor, technology, and space"}], "description": "Services cannot always be inventoried, so firms must shape demand and adjust capacity."}, {"id": "c9f2a078-45c5-496f-9251-c3885c23d46d", "type": "subtopic", "title": "Queue and Wait-Time Design", "children": [{"id": "ecdb5e45-116e-4e22-95fb-7e2fd4bbfbe0", "type": "concept", "title": "Actual wait, perceived wait, occupied time, fairness, uncertainty, and anxiety"}, {"id": "c6ea1891-56ac-4be9-a3ef-6c93418a351d", "type": "concept", "title": "Single-line queues, priority queues, virtual queues, appointments, and callbacks"}, {"id": "cb58615a-6ab3-4ff4-bc53-bdf3298fa2dd", "type": "concept", "title": "Designing information, entertainment, and choice into waits"}], "description": "Waiting is both an operations problem and an emotional customer-experience problem."}, {"id": "658d195c-74dd-4b7f-98ee-22deb94ac4a5", "type": "subtopic", "title": "Service Operations Linkage", "children": [{"id": "d1af43bc-55e5-427c-98f3-cf1658b5cf8f", "type": "concept", "title": "Bottlenecks, service levels, throughput, cycle time, lean service, and quality management"}, {"id": "ff32e858-8cfa-4af7-b31b-b4ea164e6eb4", "type": "concept", "title": "Automation, escalation, triage, and disruption planning"}, {"id": "97de1d1d-c132-456a-ba73-e51faad47ff6", "type": "concept", "title": "Customer promises that operations can keep"}], "description": "Marketing decisions must respect bottlenecks, service levels, and operational resilience."}]}, {"id": "30f1cca3-5fad-46b0-b5aa-46d9545e91da", "type": "topic", "title": "Relationship Marketing, CRM, Loyalty, and Customer Lifetime Value", "description": "Build long-term customer relationships through retention, loyalty programs, personalization, and customer equity management.", "children": [{"id": "81c44ae9-5a56-4abf-8b49-f0b659cc8ab0", "type": "subtopic", "title": "Relationship Marketing Logic", "children": [{"id": "0b7e3d7c-8923-4df9-bbdf-b0852504fb65", "type": "concept", "title": "Acquisition, onboarding, retention, cross-sell, up-sell, win-back, and advocacy"}, {"id": "7bf61657-807d-4007-95c6-25aac582830f", "type": "concept", "title": "Trust, commitment, switching costs, habit, and relationship quality"}, {"id": "f90d94df-a421-4a1f-818c-d1860644e1ee", "type": "concept", "title": "Relationship strength across subscriptions, memberships, and professional services"}], "description": "Services often profit from durable relationships rather than one-time transactions."}, {"id": "af017f5b-7b2e-45b7-acf3-242ff1eeb69c", "type": "subtopic", "title": "CRM and Loyalty Programs", "children": [{"id": "cb319cb0-d4c8-4111-bb9e-44f2326c9c7d", "type": "concept", "title": "Customer data, segmentation, personalization, loyalty tiers, rewards, and lifecycle communications"}, {"id": "ed56ef72-d19b-485b-a627-100d61ec5122", "type": "concept", "title": "Service history, preferences, next-best-action, and customer care integration"}, {"id": "1626d78b-2d90-4d50-97e5-70b4f1e39dd7", "type": "concept", "title": "Program economics and customer-perceived fairness"}], "description": "CRM systems and loyalty programs should create mutual value, not just more messaging."}, {"id": "ddfdb743-0b9f-4ed4-8c2a-758cefda37a4", "type": "subtopic", "title": "Customer Lifetime Value and Customer Equity", "children": [{"id": "96a5c925-9a58-4c38-9e63-166b6b816485", "type": "concept", "title": "CLV, retention rate, churn, margin, discount rate, customer equity, and cohort analysis"}, {"id": "b43af5c1-b159-4223-ab00-6d50a4b6b5d8", "type": "concept", "title": "High-value customers, service tiers, and ethical personalization"}, {"id": "363c9206-97d8-4956-b6bd-325829adca4e", "type": "concept", "title": "Avoiding neglect of low-value or vulnerable customers"}], "description": "CLV helps firms decide where to invest service resources and relationship effort."}]}, {"id": "1b2ff3e7-ed49-4ed5-9da5-0b417e4fc9c3", "type": "topic", "title": "Digital Services, Self-Service Technologies, Platforms, and AI", "description": "Evaluate how digital channels, platforms, automation, chatbots, and AI reshape service delivery and customer experience.", "children": [{"id": "10740a5f-319a-48c6-a1b4-e7d3fe1769d4", "type": "subtopic", "title": "Self-Service and Omnichannel Delivery", "children": [{"id": "9cd12d65-87bc-4c8a-b600-90edcc886679", "type": "concept", "title": "Kiosks, apps, portals, IVR, online scheduling, knowledge bases, and omnichannel support"}, {"id": "3358edb4-6b97-4e90-958b-6d4a50b8cf4c", "type": "concept", "title": "Customer readiness, usability, channel choice, and assisted digital service"}, {"id": "b42ef686-1cbe-4137-85dc-8c3092562255", "type": "concept", "title": "Seamless handoff across digital, phone, store, and field channels"}], "description": "Digital self-service can increase convenience but also shifts work to customers."}, {"id": "1e04bd61-8f90-4097-a845-bb4d157afc96", "type": "subtopic", "title": "Platforms and Service Ecosystems", "children": [{"id": "e6e8fdee-b014-4b32-bbeb-5126b5e80150", "type": "concept", "title": "Marketplaces, gig platforms, ratings, trust systems, network effects, and governance"}, {"id": "3be272f7-7884-45e6-9265-825e578f2486", "type": "concept", "title": "Service partners, franchisees, contractors, and ecosystem quality control"}, {"id": "512a1eb8-ed28-42d2-9d33-faf078542916", "type": "concept", "title": "Accountability when the brand does not directly perform the service"}], "description": "Many services are delivered through platforms that coordinate multiple actors."}, {"id": "fb37363c-340f-4e25-9c16-96c610affb67", "type": "subtopic", "title": "AI-Enabled Service", "children": [{"id": "04c60e9b-3ec2-4736-94c1-c1a664fab64e", "type": "concept", "title": "Chatbots, recommendation engines, predictive service, automated triage, and agent assist"}, {"id": "9607f773-af45-4cd7-92e6-b3f8c7cec8b6", "type": "concept", "title": "Human-in-the-loop, transparency, bias, privacy, and service failure risk"}, {"id": "4c870778-db3c-4923-bccb-7c73618f7d86", "type": "concept", "title": "Designing AI that supports rather than frustrates customers"}], "description": "AI can scale personalization and support, but it changes trust, transparency, and escalation expectations."}]}, {"id": "3c12fbc6-bf90-4364-a3c2-ec3a8b719ea6", "type": "topic", "title": "Service Analytics, CX Metrics, and Continuous Improvement", "description": "Use metrics, dashboards, experiments, and feedback loops to manage and improve service performance.", "children": [{"id": "065bfba4-69db-41a7-a091-53131fb3581f", "type": "subtopic", "title": "Service Metrics System", "children": [{"id": "ac30b79d-048d-4d12-b7a5-484fb1ece281", "type": "concept", "title": "NPS, CSAT, CES, retention, churn, first-contact resolution, wait time, service level, and complaint rate"}, {"id": "427d4fef-8f92-4f40-bb9b-70fde843fe9c", "type": "concept", "title": "Customer lifetime value, revenue per user, repeat purchase, and referral"}, {"id": "b98de4ce-ab67-4dad-9820-2c04cd419321", "type": "concept", "title": "Metric selection by service strategy"}], "description": "Metrics help managers connect customer experience, operations, employee experience, and financial outcomes."}, {"id": "3b593c4a-4c36-4271-a558-24a1691246fa", "type": "subtopic", "title": "Analytics and Experimentation", "children": [{"id": "c3c1779c-a860-47f8-943e-002e5187938e", "type": "concept", "title": "A/B testing, journey analytics, text analytics, cohort analysis, driver analysis, and attribution"}, {"id": "bf6724e6-0d4c-4275-b955-00dec6920086", "type": "concept", "title": "Root-cause analysis, dashboards, alerts, and experimentation roadmaps"}, {"id": "0c195fc8-747c-428b-b9d0-90d6960befba", "type": "concept", "title": "Statistical and managerial significance"}], "description": "Service improvement benefits from testing, analytics, and disciplined measurement."}, {"id": "67092632-e67c-4732-afbf-1e163e3dcdb2", "type": "subtopic", "title": "Continuous Improvement and Governance", "children": [{"id": "661bd293-d86c-409e-813d-d28415340070", "type": "concept", "title": "Closed-loop feedback, service standards, quality audits, playbooks, and training"}, {"id": "df1d65d6-4059-40cd-a318-a773bf8dea2c", "type": "concept", "title": "Lean service, Six Sigma, process improvement, and governance forums"}, {"id": "6f3f4873-a084-44c0-acfb-61a1ae8b6cc5", "type": "concept", "title": "Turning insight into accountable change"}], "description": "Service quality improves when insight becomes a management system."}]}, {"id": "49b06881-a116-4a9a-acd6-0debf5e5a39b", "type": "topic", "title": "Services Strategy Across Retail, Hospitality, Healthcare, Financial, and Professional Services", "description": "Apply services-marketing concepts across sectors with different risks, regulations, operations, and customer expectations.", "children": [{"id": "63d02012-1dce-41cb-b56c-62004f3cdc0c", "type": "subtopic", "title": "Retail and Hospitality Services", "children": [{"id": "f47da9e8-8c42-419f-9b9f-72c4dc8c7cf5", "type": "concept", "title": "Store layout, guest experience, omnichannel retailing, online travel agencies, reputation, and loyalty"}, {"id": "09c2532a-d958-4d82-8c26-e4b0c4020af0", "type": "concept", "title": "Service recovery, reviews, ratings, and local operations"}, {"id": "ab1d0cc4-ed95-476a-b78d-fe5955401468", "type": "concept", "title": "Experience as brand differentiation"}], "description": "Retail and hospitality show how atmospherics, employee behavior, operations, and digital channels shape experience."}, {"id": "9f0b3fe1-8d45-4dc0-959f-fe08a2ba6d7f", "type": "subtopic", "title": "Healthcare, Financial, and Professional Services", "children": [{"id": "9d45684c-ff75-44ba-aae3-de7a6d87603a", "type": "concept", "title": "Credence attributes, professional expertise, confidentiality, regulation, and duty of care"}, {"id": "19648aea-ec28-4403-a609-e2f3806feeb4", "type": "concept", "title": "Patient experience, financial advice, consulting, legal, education, and B2B services"}, {"id": "155ca986-1849-4423-8c47-11eb29c37bca", "type": "concept", "title": "Balancing persuasion, ethics, and client outcomes"}], "description": "High-risk and expert services require trust, compliance, empathy, clarity, and long-term relationship management."}, {"id": "05c1707c-de9d-411f-a006-4d7c593b2261", "type": "subtopic", "title": "Global and Cross-Cultural Service Strategy", "children": [{"id": "12881b6d-4743-4646-9925-1a32360b7036", "type": "concept", "title": "Cultural norms, language, service scripts, tipping, privacy, formality, and complaint behavior"}, {"id": "1c06f60b-193e-4c0b-82aa-af49b3a2e390", "type": "concept", "title": "Global service standards versus local adaptation"}, {"id": "a17cee08-ccc6-43d3-b331-a81d23d0c825", "type": "concept", "title": "Equity, accessibility, and inclusive service design"}], "description": "Service expectations vary across cultures, institutions, technologies, and labor markets."}]}, {"id": "e2c0f7f4-44b9-472d-b70f-a5efdff919b3", "type": "topic", "title": "Capstone: Service Experience Audit and Improvement Plan", "description": "Synthesize service research, blueprinting, quality diagnosis, metrics, and strategy into a complete service-improvement project.", "children": [{"id": "f3aa5275-2d29-4cf9-af68-336ea653aabd", "type": "subtopic", "title": "Service Audit and Research", "children": [{"id": "43167a08-990b-4b0d-ae54-405cf68eb63f", "type": "concept", "title": "Service selection, stakeholder map, customer segment, journey research, VOC data, and competitor scan"}, {"id": "c653cc11-6a1e-4ec0-8b1e-45d9501705d6", "type": "concept", "title": "Observation, interviews, mystery shopping, reviews, surveys, and digital analytics"}, {"id": "09b90ff3-02a6-435a-b3a4-02bf641b3f65", "type": "concept", "title": "Ethical data collection and evidence quality"}], "description": "The capstone begins with a real service, a target customer, and evidence about the current experience."}, {"id": "cd41c2ec-da4b-43a7-97b5-ff7159ad5b5e", "type": "subtopic", "title": "Blueprint and Diagnosis", "children": [{"id": "e8c43bf7-bce9-4c76-a338-7708ef4edecf", "type": "concept", "title": "Journey map, service blueprint, pain points, root causes, gaps model, and service-quality measures"}, {"id": "06d9eff5-2e76-426c-aff4-9eb7c78fc741", "type": "concept", "title": "Frontstage, backstage, support processes, people, process, and physical evidence"}, {"id": "8cf48eff-3e98-46cc-b0e8-0cf5287da4a1", "type": "concept", "title": "Prioritizing issues by customer impact and business value"}], "description": "Students translate research into a map of the service system and its failure points."}, {"id": "d79c1a84-e941-4304-a2f2-8133a406601f", "type": "subtopic", "title": "Improvement Plan and Executive Readout", "children": [{"id": "dcae366d-6aad-4d99-9f24-73a11ac87458", "type": "concept", "title": "Service concept, recovery plan, metrics, training, technology, pricing or capacity implications, and implementation roadmap"}, {"id": "d7d154c2-dabc-4ea4-9969-dd3ba878d6ce", "type": "concept", "title": "Business case, risks, quick wins, and long-term changes"}, {"id": "efccbffa-2cee-47e7-9064-5f4dbac11ac0", "type": "concept", "title": "Executive presentation, appendix, and reflection on limitations"}], "description": "The final deliverable should be usable by managers, not just descriptive."}]}], "dbBacked": true}$svmkjson$::jsonb,
  true,
  false,
  'course',
  'public'
where not exists (
  select 1 from public.learning_paths where slug = 'services-marketing'
);

update public.learning_paths
set
  title = 'Services Marketing',
  goal = 'Services Marketing',
  summary = 'Frame services as experiences, performances, relationships, and systems that require different marketing logic than tangible goods.',
  data = $svmkjson${"slug": "services-marketing", "title": "Services Marketing", "description": "Frame services as experiences, performances, relationships, and systems that require different marketing logic than tangible goods.", "topics": [{"id": "cd6b658e-543a-425b-b31b-279074ea005e", "type": "topic", "title": "Services Marketing Foundations and the Service-Dominant Economy", "description": "Frame services as experiences, performances, relationships, and systems that require different marketing logic than tangible goods.", "children": [{"id": "a063ca97-baaa-462f-bcdc-bc9a8e1e5f0e", "type": "subtopic", "title": "Why Services Need Distinct Marketing", "children": [{"id": "52a04915-60b3-4b03-9c1a-f085df3ea576", "type": "concept", "title": "Service economy, experience economy, service-dominant logic, value-in-use, and co-creation"}, {"id": "29847315-306a-458c-ad34-91faf30b956c", "type": "concept", "title": "Services as performances, processes, promises, and relationships"}, {"id": "f88fb4bb-7cfa-4c57-ae7c-9efeb3e1dd92", "type": "concept", "title": "Implications for positioning, delivery, measurement, and loyalty"}], "description": "Services are often bought before they can be fully evaluated, which makes trust, evidence, relationships, and experience design central."}, {"id": "a8f4c51a-8a52-4986-be41-beaaaf8ad5cb", "type": "subtopic", "title": "Service Strategy and the Marketing Mix", "children": [{"id": "1cbe2eec-1385-41aa-9716-6c46d1891302", "type": "concept", "title": "7Ps: product, price, place, promotion, people, process, and physical evidence"}, {"id": "1d91a4d1-716f-4eb0-99e1-94ee00e2ce7f", "type": "concept", "title": "Service concept, value proposition, target segment, and competitive advantage"}, {"id": "54004e87-673c-4d44-9c07-e305a85acf83", "type": "concept", "title": "Service standards, brand promise, and delivery capability"}], "description": "Students learn how the classic marketing mix expands when the offering is performed through people, process, and evidence."}, {"id": "d23aa913-5f99-4047-9911-7c04a17a3336", "type": "subtopic", "title": "Service Categories and Business Models", "children": [{"id": "010693d1-7c86-40e6-a019-fd29fc5e8a05", "type": "concept", "title": "B2C, B2B, professional, hospitality, retail, healthcare, financial, subscription, and platform services"}, {"id": "d2f3307c-d9a2-4af8-b11c-3da8c1fcf9c3", "type": "concept", "title": "High-contact versus low-contact services"}, {"id": "95d5a4e5-58d8-4054-ac7a-9f2607c5e646", "type": "concept", "title": "Membership, recurring revenue, freemium, marketplace, and usage-based models"}], "description": "Services differ by customer contact, customization, risk, duration, expertise, and delivery channel."}]}, {"id": "f499093d-c580-4fba-ad91-3ddfe78d7946", "type": "topic", "title": "Services vs. Goods, IHIP Characteristics, and Customer Participation", "description": "Analyze intangibility, heterogeneity, inseparability, perishability, ownership, and co-production as core service-marketing challenges.", "children": [{"id": "94c04dc4-b3a2-4033-a60d-28e1d298f9bb", "type": "subtopic", "title": "IHIP Characteristics", "children": [{"id": "3f9a7d52-ddc0-46c7-aeb9-1f68cb5c3401", "type": "concept", "title": "Intangibility, heterogeneity, inseparability, and perishability"}, {"id": "6ec26362-55ec-4043-92f8-a8779d1d6735", "type": "concept", "title": "Ownership, simultaneity, variability, and performance risk"}, {"id": "024b85c3-9719-4741-9a54-186ea139e246", "type": "concept", "title": "How IHIP affects communication, pricing, quality control, and operations"}], "description": "The IHIP framework helps explain why services are harder to evaluate, standardize, store, and separate from delivery."}, {"id": "1e0d9391-3dd6-472b-ae68-8827a8cff83b", "type": "subtopic", "title": "Customer Participation and Co-Production", "children": [{"id": "b370e5dc-173e-4e8b-90d8-ef319b9544f1", "type": "concept", "title": "Customer roles, scripts, responsibilities, readiness, and onboarding"}, {"id": "8a3eb81c-70b4-46d4-a1bf-d792394cd304", "type": "concept", "title": "Co-production, co-creation, self-service, and customer education"}, {"id": "ed2d9767-77c3-4d35-b0bf-499b0107a88f", "type": "concept", "title": "Managing customer error, anxiety, and participation burden"}], "description": "Customers often help produce the service, so their behavior affects quality, cost, and outcomes."}, {"id": "5b697866-c6e7-4f59-ab1c-589a24226008", "type": "subtopic", "title": "Risk and Trust in Service Evaluation", "children": [{"id": "848b0b87-a083-4076-8b2d-37146c6bff62", "type": "concept", "title": "Search, experience, and credence attributes"}, {"id": "9c2c9d0b-b731-43fc-9bdc-de6d441dd09c", "type": "concept", "title": "Perceived risk, trust, guarantees, reviews, referrals, and reputation"}, {"id": "d9e414c7-05ea-4bb0-8d37-74557742fcb2", "type": "concept", "title": "Reducing uncertainty through proof, transparency, and trials"}], "description": "Services can be difficult to judge before purchase, so customers use signals and relationships to reduce risk."}]}, {"id": "b4e4fd16-5cfe-4a59-a133-d0b05a4d163a", "type": "topic", "title": "Customer Expectations, Perceptions, and Service Quality", "description": "Understand how customers form expectations, evaluate service encounters, and judge quality before, during, and after consumption.", "children": [{"id": "b81636e3-73a9-48b6-b2cb-e5d4eba22411", "type": "subtopic", "title": "Expectation Formation", "children": [{"id": "04ec7ead-fc49-4323-9c51-c0f2b3fa1438", "type": "concept", "title": "Desired service, adequate service, predicted service, and zone of tolerance"}, {"id": "37a2af3b-787d-4113-b50d-83b8d0817d15", "type": "concept", "title": "Word of mouth, prior experience, advertising, price, reviews, and situational factors"}, {"id": "28270ec9-4db0-42b2-8cb6-e738dfc3fe68", "type": "concept", "title": "Managing promises without overpromising"}], "description": "Customers compare performance against expected, desired, and adequate service levels."}, {"id": "d026499e-6ba5-4e6b-8876-57441cb9f49f", "type": "subtopic", "title": "Perceived Service Quality", "children": [{"id": "307b3012-5da6-4fed-b66c-04ab214458cb", "type": "concept", "title": "Technical quality, functional quality, interaction quality, and outcome quality"}, {"id": "598463e9-9558-4c64-9d69-37e49da63df4", "type": "concept", "title": "Reliability, responsiveness, assurance, empathy, and tangibles"}, {"id": "c50fb10f-9a68-4225-bbfe-8c884a836e3e", "type": "concept", "title": "Moments of truth and cumulative experience"}], "description": "Quality is judged through the customer's perception of both outcome and process."}, {"id": "0b15dd39-2fa9-403c-81f5-fd5ea0126905", "type": "subtopic", "title": "Satisfaction, Delight, and Loyalty", "children": [{"id": "f7c19b7b-256d-4408-a377-991bb72ffa1e", "type": "concept", "title": "Satisfaction, dissatisfaction, delight, trust, commitment, and advocacy"}, {"id": "2aa78965-d413-4203-81e4-5873d903dc90", "type": "concept", "title": "Post-purchase evaluation, confirmation/disconfirmation, and emotional memory"}, {"id": "b3bb2732-6044-4c31-b2c8-e0eaeb4da941", "type": "concept", "title": "Retention, churn, referral, and share of wallet"}], "description": "Satisfaction is not the same as loyalty, but it strongly shapes retention, advocacy, and repeat use."}]}, {"id": "c3d731e2-4dea-45e3-b1a8-b8e4d3ed6ce1", "type": "topic", "title": "SERVQUAL, Gaps Model, and Voice-of-Customer Measurement", "description": "Use service-quality frameworks and feedback systems to diagnose failures and prioritize improvement.", "children": [{"id": "2ee1c74f-7586-4f01-bb84-6045fbb59929", "type": "subtopic", "title": "SERVQUAL and Service Quality Dimensions", "children": [{"id": "90880d2c-4767-494b-b945-d0f2436512da", "type": "concept", "title": "Reliability, responsiveness, assurance, empathy, and tangibles"}, {"id": "0fbedb2c-a9c3-4b8c-a486-e9225bf62580", "type": "concept", "title": "Expectation-perception gaps, scale construction, and interpretation"}, {"id": "331e57d2-ee33-454b-b550-50d37b1602d5", "type": "concept", "title": "Strengths, limits, and alternatives to SERVQUAL"}], "description": "SERVQUAL gives students a structured way to measure service expectations and perceptions."}, {"id": "884438e1-dc55-4762-90ad-530e273a04f3", "type": "subtopic", "title": "Gaps Model Diagnosis", "children": [{"id": "dcd7f2d0-0ba7-44b3-b756-0790238c315f", "type": "concept", "title": "Knowledge gap, standards gap, delivery gap, communication gap, and customer gap"}, {"id": "99764b43-22fd-4419-828b-50cf85c3ceac", "type": "concept", "title": "Customer research, service standards, training, operations, and external promises"}, {"id": "caf2afed-379f-42be-9d61-5d1ca7c66616", "type": "concept", "title": "Prioritizing fixes by root cause and impact"}], "description": "The gaps model helps connect customer dissatisfaction to organizational causes."}, {"id": "995a3ac9-316c-4acc-b7f3-7e1a16d4d809", "type": "subtopic", "title": "Voice of Customer Systems", "children": [{"id": "ae8d42b2-4363-4f8c-b7f4-57dc4d9c230b", "type": "concept", "title": "Transactional surveys, relationship surveys, NPS, CSAT, CES, reviews, complaints, and social listening"}, {"id": "97a3c56d-a3e2-4319-bea8-3b92fb01500c", "type": "concept", "title": "Closed-loop feedback, text analytics, dashboards, and escalation"}, {"id": "fa301106-ff30-4821-b8f9-76c55dc6829b", "type": "concept", "title": "Sampling bias, survey fatigue, and feedback representativeness"}], "description": "Modern service firms need continuous listening systems, not one-off surveys."}]}, {"id": "8e0be73e-87b8-4653-a736-fb332faa2bd9", "type": "topic", "title": "Service Design, Customer Journey Mapping, and Blueprinting", "description": "Translate customer insight into designed experiences, touchpoints, backstage systems, and operational requirements.", "children": [{"id": "64a54dae-e49a-4d61-b505-330f3670a941", "type": "subtopic", "title": "Journey Mapping", "children": [{"id": "39834eea-1a90-48ba-9244-d57a690aba47", "type": "concept", "title": "Stages, goals, emotions, pain points, channels, touchpoints, and moments that matter"}, {"id": "4dd331d3-402c-4809-ac39-f164c8168e12", "type": "concept", "title": "Current-state and future-state journey maps"}, {"id": "720e778a-df61-40c9-83bd-e37afaef06f5", "type": "concept", "title": "Journey evidence from interviews, observation, analytics, and feedback"}], "description": "Journey maps help teams see the customer's end-to-end experience across stages and touchpoints."}, {"id": "57b708ea-608b-4d6f-b59d-b7b1d30e0304", "type": "subtopic", "title": "Service Blueprinting", "children": [{"id": "4c4816f4-a13f-4f6a-9dee-e317178d7869", "type": "concept", "title": "Customer actions, frontstage, backstage, support processes, line of interaction, and line of visibility"}, {"id": "ae36feb8-3238-4487-a297-8ec47d322d5b", "type": "concept", "title": "Failure points, handoffs, wait states, and operational dependencies"}, {"id": "a55bff3f-cb35-4ae7-9e8c-455204a7b0b3", "type": "concept", "title": "Blueprints as design, training, and improvement tools"}], "description": "Blueprints connect customer experience to frontline actions, backstage work, systems, and support processes."}, {"id": "e740ce3e-f376-4373-88ad-f84bd1c2d89b", "type": "subtopic", "title": "Prototyping and Service Innovation", "children": [{"id": "ed868d50-00e2-4b5a-90f8-47d3c1294c55", "type": "concept", "title": "Experience prototypes, role play, service scripts, pilots, concierge tests, and minimum viable services"}, {"id": "91a30852-716b-4ca7-9b86-7178a60c03aa", "type": "concept", "title": "Concept testing, usability testing, and experience labs"}, {"id": "ed207c75-b5ca-49a3-a2fb-7254f530edae", "type": "concept", "title": "Iteration from insight to operating model"}], "description": "Service ideas can be tested before full rollout through prototypes and pilots."}]}, {"id": "594c3953-c805-496e-a04e-3513b10a91e7", "type": "topic", "title": "Service Encounters, People, Culture, and Internal Marketing", "description": "Study frontline employees, service culture, emotional labor, empowerment, and internal alignment as part of the marketing system.", "children": [{"id": "b87f2bac-de02-4d5f-94e8-592cc453c68c", "type": "subtopic", "title": "Frontline Service Encounters", "children": [{"id": "c8405d2c-cf93-467b-a088-5159d0c12948", "type": "concept", "title": "Moments of truth, service scripts, empathy, responsiveness, problem solving, and rapport"}, {"id": "81956b9f-6d54-49be-93e9-8b52d43726d3", "type": "concept", "title": "Customer-contact employees and boundary-spanning roles"}, {"id": "63dd13d9-385f-4d72-a4db-cda67b344dec", "type": "concept", "title": "Consistency without robotic delivery"}], "description": "The service encounter is where brand promises become real for customers."}, {"id": "7fbd80e9-2f63-4856-8769-5f648c8eae4f", "type": "subtopic", "title": "Service Culture and Internal Marketing", "children": [{"id": "7372add1-afd6-48f1-8c7e-19ea207c3819", "type": "concept", "title": "Internal marketing, employer brand, service vision, training, communication, and recognition"}, {"id": "ae0c321b-6b62-4924-af76-21e1dde91359", "type": "concept", "title": "Empowerment, psychological safety, leadership, and role clarity"}, {"id": "4af1d0c1-5de5-4ba4-b4c7-0deac6f87dd7", "type": "concept", "title": "Aligning incentives with customer experience"}], "description": "Employees deliver better service when the organization markets the promise internally as well as externally."}, {"id": "158a01a9-a168-4a71-aedf-dd792558b80a", "type": "subtopic", "title": "Emotional Labor and Employee Experience", "children": [{"id": "f9b215a8-4fe1-4136-85eb-771c12cafdf0", "type": "concept", "title": "Emotional labor, burnout, conflict, difficult customers, and service climate"}, {"id": "ecfacd89-1f55-459c-8e6d-13ed2eeab0f3", "type": "concept", "title": "Employee experience, engagement, staffing, and retention"}, {"id": "5f70f6d3-4f12-49b6-afcc-e8bde5e9d5f1", "type": "concept", "title": "Linking EX, CX, productivity, and service quality"}], "description": "World-class service requires caring for the people who perform care, expertise, hospitality, or support."}]}, {"id": "621db7fd-5602-440e-9334-3d1923229da0", "type": "topic", "title": "Physical Evidence, Servicescapes, Atmospherics, and Digital Interfaces", "description": "Examine how tangible cues, spaces, interfaces, and sensory evidence make intangible services understandable and trustworthy.", "children": [{"id": "a242f18b-e2df-4f01-bdbf-583f177310d5", "type": "subtopic", "title": "Physical Evidence and Tangible Cues", "children": [{"id": "62f77db8-9caa-4523-848e-07fa3a3b5d50", "type": "concept", "title": "Signage, uniforms, equipment, documents, packaging, cleanliness, certifications, and visible process cues"}, {"id": "a9680931-17ab-4f09-baef-8fd53ad18609", "type": "concept", "title": "Risk reduction, brand meaning, and quality signaling"}, {"id": "8976f737-64a2-4cd0-a10b-4613a34817ba", "type": "concept", "title": "Managing evidence across high- and low-contact services"}], "description": "Customers use tangible signals to judge intangible services before and during consumption."}, {"id": "178f1030-ab48-4a90-9bf8-d23ec72fe59f", "type": "subtopic", "title": "Servicescapes and Atmospherics", "children": [{"id": "3c835179-27db-459a-9b5e-9175bffc6013", "type": "concept", "title": "Ambient conditions, layout, spatial flow, symbols, artifacts, scent, lighting, sound, and crowding"}, {"id": "20ea0171-3fa1-453e-920e-72c1302d120e", "type": "concept", "title": "Retail, hospitality, healthcare, banking, and professional-service environments"}, {"id": "262ae921-1c53-4a91-9f6d-51f2f8ba0f34", "type": "concept", "title": "Accessibility, inclusion, safety, and sensory design"}], "description": "The service environment shapes emotion, behavior, trust, dwell time, and perceived quality."}, {"id": "eccbc21f-703d-4dcd-8ae2-5825486cd2b4", "type": "subtopic", "title": "Digital Interfaces as Servicescapes", "children": [{"id": "7478ff86-ef3d-42cc-a97f-b54b6c57399c", "type": "concept", "title": "UX, usability, information architecture, microcopy, onboarding, and error states"}, {"id": "22ebcd19-3b5d-43c4-9f34-2c7a9da94329", "type": "concept", "title": "Self-service portals, mobile apps, chatbots, and omnichannel consistency"}, {"id": "67023f6d-f831-4805-a466-aad669143847", "type": "concept", "title": "Trust cues, security cues, and digital accessibility"}], "description": "Websites, apps, kiosks, and chat interfaces are modern service environments."}]}, {"id": "108a4ca9-071b-4569-bef1-90cbdcf0efa6", "type": "topic", "title": "Service Recovery, Complaint Management, and Customer Trust", "description": "Learn how firms respond to failure, rebuild trust, and turn breakdowns into learning and loyalty opportunities.", "children": [{"id": "31237cd4-dc86-4651-8906-fd2b8283cc21", "type": "subtopic", "title": "Service Failure Types", "children": [{"id": "4e1bf243-bc69-41db-8d9f-54bfdc970649", "type": "concept", "title": "Core service failure, process failure, interaction failure, policy failure, and outcome failure"}, {"id": "6fc61209-331a-43bd-88a2-dde5c66939cc", "type": "concept", "title": "Severity, controllability, recurrence, and customer vulnerability"}, {"id": "133a0e64-6686-4193-bca5-80855f2a69bb", "type": "concept", "title": "Detecting failures before complaints appear"}], "description": "Different failures require different recovery strategies and communication."}, {"id": "b26d4339-c9be-46b2-aa83-aa1f8d988bda", "type": "subtopic", "title": "Recovery Strategy", "children": [{"id": "7c4a076a-260a-4173-afb1-3074e2e4c803", "type": "concept", "title": "Apology, explanation, speed, empathy, compensation, correction, and follow-up"}, {"id": "98b03b46-a661-42c1-8a11-f97cc10d9ed3", "type": "concept", "title": "Procedural, interactional, and distributive justice"}, {"id": "71150cfc-036c-44fd-9a9c-bf54791c57db", "type": "concept", "title": "Service guarantees and recovery empowerment"}], "description": "Recovery restores fairness, confidence, and relationship value after a breakdown."}, {"id": "3f25039e-41a1-4c25-9f1d-2038b8206c83", "type": "subtopic", "title": "Complaint Learning and Trust Repair", "children": [{"id": "5b825420-87ca-4ae3-9cb2-f7f1f495865a", "type": "concept", "title": "Complaint channels, escalation, root-cause analysis, closed-loop learning, and prevention"}, {"id": "bb9a38b5-7caf-431f-87eb-5e6cc946f112", "type": "concept", "title": "Trust, forgiveness, switching, negative word of mouth, and recovery paradox"}, {"id": "9d02edcb-6b42-45d9-a56f-be6ef2cb2b4c", "type": "concept", "title": "When recovery can and cannot create loyalty"}], "description": "Complaints are not only costs; they are high-value data about system weakness."}]}, {"id": "0f5b6177-b38f-49bc-91cf-11baeb1a5580", "type": "topic", "title": "Service Pricing, Revenue Management, and Value Communication", "description": "Apply pricing logic to intangible, time-sensitive, capacity-constrained, and relationship-based services.", "children": [{"id": "ef2c7213-1c22-4316-a347-cc75257cafec", "type": "subtopic", "title": "Pricing Intangible Value", "children": [{"id": "8d5938da-64fe-41ec-b807-2c41e52683ec", "type": "concept", "title": "Value-based pricing, cost-based pricing, competition-based pricing, and outcome-based pricing"}, {"id": "699589db-0cac-42d7-86f9-57c62d731250", "type": "concept", "title": "Hourly, subscription, retainer, freemium, usage-based, and bundled pricing"}, {"id": "e6d560ce-c819-47ea-bc5f-34111f1f87b0", "type": "concept", "title": "Communicating expertise, convenience, reliability, and peace of mind"}], "description": "Service pricing must communicate value for outcomes that may be uncertain, delayed, or co-produced."}, {"id": "d51fc4de-773a-4ee5-9325-a13d16c67e78", "type": "subtopic", "title": "Revenue and Yield Management", "children": [{"id": "92c556e2-efcb-4d39-9055-064ed59e5249", "type": "concept", "title": "Yield management, revenue management, dynamic pricing, peak/off-peak pricing, and load factors"}, {"id": "9e219d38-89db-478d-99d4-4c0fd92a7339", "type": "concept", "title": "Hotels, airlines, restaurants, events, ride-share, and appointment services"}, {"id": "588d26a8-1000-4570-a9d4-2d7bfcf2524a", "type": "concept", "title": "Fairness perceptions and transparency"}], "description": "Capacity-constrained services often need dynamic pricing to balance demand and profitability."}, {"id": "759d0825-9e49-41eb-abb6-e1b6f3ef3713", "type": "subtopic", "title": "Price Fairness and Behavioral Response", "children": [{"id": "6c5606a1-9b56-477f-b851-ad4a88700b56", "type": "concept", "title": "Reference price, fairness, partitioned pricing, fees, discounts, tipping, and subscriptions"}, {"id": "69328e14-5426-4205-86ab-e5d499acc12b", "type": "concept", "title": "Willingness to pay, price sensitivity, and perceived sacrifice"}, {"id": "5c42b4f9-2ae6-4ec6-9a55-679eaa6596c7", "type": "concept", "title": "Avoiding hidden-fee backlash and trust erosion"}], "description": "Customers react not only to price level but also to the perceived fairness of rules and fees."}]}, {"id": "8228cfc2-a3aa-4a61-bcba-f82e19db8763", "type": "topic", "title": "Demand, Capacity, Queues, and Wait-Time Experience Design", "description": "Manage demand and capacity while designing fair, transparent, and emotionally intelligent waiting experiences.", "children": [{"id": "28f7b675-c13c-428b-9d46-cc58afcbad76", "type": "subtopic", "title": "Demand and Capacity Management", "children": [{"id": "ab5da271-f3be-47f9-9534-d9785162ed53", "type": "concept", "title": "Perishability, capacity utilization, reservations, appointments, staffing, and demand smoothing"}, {"id": "dc8300b1-5e2a-4ff8-a515-4c0dec2cd523", "type": "concept", "title": "Peak demand, idle capacity, seasonality, and no-shows"}, {"id": "4db247f6-0f58-41a0-8efc-d092d876f3db", "type": "concept", "title": "Matching demand with labor, technology, and space"}], "description": "Services cannot always be inventoried, so firms must shape demand and adjust capacity."}, {"id": "c9f2a078-45c5-496f-9251-c3885c23d46d", "type": "subtopic", "title": "Queue and Wait-Time Design", "children": [{"id": "ecdb5e45-116e-4e22-95fb-7e2fd4bbfbe0", "type": "concept", "title": "Actual wait, perceived wait, occupied time, fairness, uncertainty, and anxiety"}, {"id": "c6ea1891-56ac-4be9-a3ef-6c93418a351d", "type": "concept", "title": "Single-line queues, priority queues, virtual queues, appointments, and callbacks"}, {"id": "cb58615a-6ab3-4ff4-bc53-bdf3298fa2dd", "type": "concept", "title": "Designing information, entertainment, and choice into waits"}], "description": "Waiting is both an operations problem and an emotional customer-experience problem."}, {"id": "658d195c-74dd-4b7f-98ee-22deb94ac4a5", "type": "subtopic", "title": "Service Operations Linkage", "children": [{"id": "d1af43bc-55e5-427c-98f3-cf1658b5cf8f", "type": "concept", "title": "Bottlenecks, service levels, throughput, cycle time, lean service, and quality management"}, {"id": "ff32e858-8cfa-4af7-b31b-b4ea164e6eb4", "type": "concept", "title": "Automation, escalation, triage, and disruption planning"}, {"id": "97de1d1d-c132-456a-ba73-e51faad47ff6", "type": "concept", "title": "Customer promises that operations can keep"}], "description": "Marketing decisions must respect bottlenecks, service levels, and operational resilience."}]}, {"id": "30f1cca3-5fad-46b0-b5aa-46d9545e91da", "type": "topic", "title": "Relationship Marketing, CRM, Loyalty, and Customer Lifetime Value", "description": "Build long-term customer relationships through retention, loyalty programs, personalization, and customer equity management.", "children": [{"id": "81c44ae9-5a56-4abf-8b49-f0b659cc8ab0", "type": "subtopic", "title": "Relationship Marketing Logic", "children": [{"id": "0b7e3d7c-8923-4df9-bbdf-b0852504fb65", "type": "concept", "title": "Acquisition, onboarding, retention, cross-sell, up-sell, win-back, and advocacy"}, {"id": "7bf61657-807d-4007-95c6-25aac582830f", "type": "concept", "title": "Trust, commitment, switching costs, habit, and relationship quality"}, {"id": "f90d94df-a421-4a1f-818c-d1860644e1ee", "type": "concept", "title": "Relationship strength across subscriptions, memberships, and professional services"}], "description": "Services often profit from durable relationships rather than one-time transactions."}, {"id": "af017f5b-7b2e-45b7-acf3-242ff1eeb69c", "type": "subtopic", "title": "CRM and Loyalty Programs", "children": [{"id": "cb319cb0-d4c8-4111-bb9e-44f2326c9c7d", "type": "concept", "title": "Customer data, segmentation, personalization, loyalty tiers, rewards, and lifecycle communications"}, {"id": "ed56ef72-d19b-485b-a627-100d61ec5122", "type": "concept", "title": "Service history, preferences, next-best-action, and customer care integration"}, {"id": "1626d78b-2d90-4d50-97e5-70b4f1e39dd7", "type": "concept", "title": "Program economics and customer-perceived fairness"}], "description": "CRM systems and loyalty programs should create mutual value, not just more messaging."}, {"id": "ddfdb743-0b9f-4ed4-8c2a-758cefda37a4", "type": "subtopic", "title": "Customer Lifetime Value and Customer Equity", "children": [{"id": "96a5c925-9a58-4c38-9e63-166b6b816485", "type": "concept", "title": "CLV, retention rate, churn, margin, discount rate, customer equity, and cohort analysis"}, {"id": "b43af5c1-b159-4223-ab00-6d50a4b6b5d8", "type": "concept", "title": "High-value customers, service tiers, and ethical personalization"}, {"id": "363c9206-97d8-4956-b6bd-325829adca4e", "type": "concept", "title": "Avoiding neglect of low-value or vulnerable customers"}], "description": "CLV helps firms decide where to invest service resources and relationship effort."}]}, {"id": "1b2ff3e7-ed49-4ed5-9da5-0b417e4fc9c3", "type": "topic", "title": "Digital Services, Self-Service Technologies, Platforms, and AI", "description": "Evaluate how digital channels, platforms, automation, chatbots, and AI reshape service delivery and customer experience.", "children": [{"id": "10740a5f-319a-48c6-a1b4-e7d3fe1769d4", "type": "subtopic", "title": "Self-Service and Omnichannel Delivery", "children": [{"id": "9cd12d65-87bc-4c8a-b600-90edcc886679", "type": "concept", "title": "Kiosks, apps, portals, IVR, online scheduling, knowledge bases, and omnichannel support"}, {"id": "3358edb4-6b97-4e90-958b-6d4a50b8cf4c", "type": "concept", "title": "Customer readiness, usability, channel choice, and assisted digital service"}, {"id": "b42ef686-1cbe-4137-85dc-8c3092562255", "type": "concept", "title": "Seamless handoff across digital, phone, store, and field channels"}], "description": "Digital self-service can increase convenience but also shifts work to customers."}, {"id": "1e04bd61-8f90-4097-a845-bb4d157afc96", "type": "subtopic", "title": "Platforms and Service Ecosystems", "children": [{"id": "e6e8fdee-b014-4b32-bbeb-5126b5e80150", "type": "concept", "title": "Marketplaces, gig platforms, ratings, trust systems, network effects, and governance"}, {"id": "3be272f7-7884-45e6-9265-825e578f2486", "type": "concept", "title": "Service partners, franchisees, contractors, and ecosystem quality control"}, {"id": "512a1eb8-ed28-42d2-9d33-faf078542916", "type": "concept", "title": "Accountability when the brand does not directly perform the service"}], "description": "Many services are delivered through platforms that coordinate multiple actors."}, {"id": "fb37363c-340f-4e25-9c16-96c610affb67", "type": "subtopic", "title": "AI-Enabled Service", "children": [{"id": "04c60e9b-3ec2-4736-94c1-c1a664fab64e", "type": "concept", "title": "Chatbots, recommendation engines, predictive service, automated triage, and agent assist"}, {"id": "9607f773-af45-4cd7-92e6-b3f8c7cec8b6", "type": "concept", "title": "Human-in-the-loop, transparency, bias, privacy, and service failure risk"}, {"id": "4c870778-db3c-4923-bccb-7c73618f7d86", "type": "concept", "title": "Designing AI that supports rather than frustrates customers"}], "description": "AI can scale personalization and support, but it changes trust, transparency, and escalation expectations."}]}, {"id": "3c12fbc6-bf90-4364-a3c2-ec3a8b719ea6", "type": "topic", "title": "Service Analytics, CX Metrics, and Continuous Improvement", "description": "Use metrics, dashboards, experiments, and feedback loops to manage and improve service performance.", "children": [{"id": "065bfba4-69db-41a7-a091-53131fb3581f", "type": "subtopic", "title": "Service Metrics System", "children": [{"id": "ac30b79d-048d-4d12-b7a5-484fb1ece281", "type": "concept", "title": "NPS, CSAT, CES, retention, churn, first-contact resolution, wait time, service level, and complaint rate"}, {"id": "427d4fef-8f92-4f40-bb9b-70fde843fe9c", "type": "concept", "title": "Customer lifetime value, revenue per user, repeat purchase, and referral"}, {"id": "b98de4ce-ab67-4dad-9820-2c04cd419321", "type": "concept", "title": "Metric selection by service strategy"}], "description": "Metrics help managers connect customer experience, operations, employee experience, and financial outcomes."}, {"id": "3b593c4a-4c36-4271-a558-24a1691246fa", "type": "subtopic", "title": "Analytics and Experimentation", "children": [{"id": "c3c1779c-a860-47f8-943e-002e5187938e", "type": "concept", "title": "A/B testing, journey analytics, text analytics, cohort analysis, driver analysis, and attribution"}, {"id": "bf6724e6-0d4c-4275-b955-00dec6920086", "type": "concept", "title": "Root-cause analysis, dashboards, alerts, and experimentation roadmaps"}, {"id": "0c195fc8-747c-428b-b9d0-90d6960befba", "type": "concept", "title": "Statistical and managerial significance"}], "description": "Service improvement benefits from testing, analytics, and disciplined measurement."}, {"id": "67092632-e67c-4732-afbf-1e163e3dcdb2", "type": "subtopic", "title": "Continuous Improvement and Governance", "children": [{"id": "661bd293-d86c-409e-813d-d28415340070", "type": "concept", "title": "Closed-loop feedback, service standards, quality audits, playbooks, and training"}, {"id": "df1d65d6-4059-40cd-a318-a773bf8dea2c", "type": "concept", "title": "Lean service, Six Sigma, process improvement, and governance forums"}, {"id": "6f3f4873-a084-44c0-acfb-61a1ae8b6cc5", "type": "concept", "title": "Turning insight into accountable change"}], "description": "Service quality improves when insight becomes a management system."}]}, {"id": "49b06881-a116-4a9a-acd6-0debf5e5a39b", "type": "topic", "title": "Services Strategy Across Retail, Hospitality, Healthcare, Financial, and Professional Services", "description": "Apply services-marketing concepts across sectors with different risks, regulations, operations, and customer expectations.", "children": [{"id": "63d02012-1dce-41cb-b56c-62004f3cdc0c", "type": "subtopic", "title": "Retail and Hospitality Services", "children": [{"id": "f47da9e8-8c42-419f-9b9f-72c4dc8c7cf5", "type": "concept", "title": "Store layout, guest experience, omnichannel retailing, online travel agencies, reputation, and loyalty"}, {"id": "09c2532a-d958-4d82-8c26-e4b0c4020af0", "type": "concept", "title": "Service recovery, reviews, ratings, and local operations"}, {"id": "ab1d0cc4-ed95-476a-b78d-fe5955401468", "type": "concept", "title": "Experience as brand differentiation"}], "description": "Retail and hospitality show how atmospherics, employee behavior, operations, and digital channels shape experience."}, {"id": "9f0b3fe1-8d45-4dc0-959f-fe08a2ba6d7f", "type": "subtopic", "title": "Healthcare, Financial, and Professional Services", "children": [{"id": "9d45684c-ff75-44ba-aae3-de7a6d87603a", "type": "concept", "title": "Credence attributes, professional expertise, confidentiality, regulation, and duty of care"}, {"id": "19648aea-ec28-4403-a609-e2f3806feeb4", "type": "concept", "title": "Patient experience, financial advice, consulting, legal, education, and B2B services"}, {"id": "155ca986-1849-4423-8c47-11eb29c37bca", "type": "concept", "title": "Balancing persuasion, ethics, and client outcomes"}], "description": "High-risk and expert services require trust, compliance, empathy, clarity, and long-term relationship management."}, {"id": "05c1707c-de9d-411f-a006-4d7c593b2261", "type": "subtopic", "title": "Global and Cross-Cultural Service Strategy", "children": [{"id": "12881b6d-4743-4646-9925-1a32360b7036", "type": "concept", "title": "Cultural norms, language, service scripts, tipping, privacy, formality, and complaint behavior"}, {"id": "1c06f60b-193e-4c0b-82aa-af49b3a2e390", "type": "concept", "title": "Global service standards versus local adaptation"}, {"id": "a17cee08-ccc6-43d3-b331-a81d23d0c825", "type": "concept", "title": "Equity, accessibility, and inclusive service design"}], "description": "Service expectations vary across cultures, institutions, technologies, and labor markets."}]}, {"id": "e2c0f7f4-44b9-472d-b70f-a5efdff919b3", "type": "topic", "title": "Capstone: Service Experience Audit and Improvement Plan", "description": "Synthesize service research, blueprinting, quality diagnosis, metrics, and strategy into a complete service-improvement project.", "children": [{"id": "f3aa5275-2d29-4cf9-af68-336ea653aabd", "type": "subtopic", "title": "Service Audit and Research", "children": [{"id": "43167a08-990b-4b0d-ae54-405cf68eb63f", "type": "concept", "title": "Service selection, stakeholder map, customer segment, journey research, VOC data, and competitor scan"}, {"id": "c653cc11-6a1e-4ec0-8b1e-45d9501705d6", "type": "concept", "title": "Observation, interviews, mystery shopping, reviews, surveys, and digital analytics"}, {"id": "09b90ff3-02a6-435a-b3a4-02bf641b3f65", "type": "concept", "title": "Ethical data collection and evidence quality"}], "description": "The capstone begins with a real service, a target customer, and evidence about the current experience."}, {"id": "cd41c2ec-da4b-43a7-97b5-ff7159ad5b5e", "type": "subtopic", "title": "Blueprint and Diagnosis", "children": [{"id": "e8c43bf7-bce9-4c76-a338-7708ef4edecf", "type": "concept", "title": "Journey map, service blueprint, pain points, root causes, gaps model, and service-quality measures"}, {"id": "06d9eff5-2e76-426c-aff4-9eb7c78fc741", "type": "concept", "title": "Frontstage, backstage, support processes, people, process, and physical evidence"}, {"id": "8cf48eff-3e98-46cc-b0e8-0cf5287da4a1", "type": "concept", "title": "Prioritizing issues by customer impact and business value"}], "description": "Students translate research into a map of the service system and its failure points."}, {"id": "d79c1a84-e941-4304-a2f2-8133a406601f", "type": "subtopic", "title": "Improvement Plan and Executive Readout", "children": [{"id": "dcae366d-6aad-4d99-9f24-73a11ac87458", "type": "concept", "title": "Service concept, recovery plan, metrics, training, technology, pricing or capacity implications, and implementation roadmap"}, {"id": "d7d154c2-dabc-4ea4-9969-dd3ba878d6ce", "type": "concept", "title": "Business case, risks, quick wins, and long-term changes"}, {"id": "efccbffa-2cee-47e7-9064-5f4dbac11ac0", "type": "concept", "title": "Executive presentation, appendix, and reflection on limitations"}], "description": "The final deliverable should be usable by managers, not just descriptive."}]}], "dbBacked": true}$svmkjson$::jsonb,
