  ('cd6b658e-543a-425b-b31b-279074ea005e', 'd1e2f3a4-5b6c-4d81-8e82-9f0a1b2c3d41', null, 'topic'::public.curated_course_node_type, 'Services Marketing Foundations and the Service-Dominant Economy', 'Frame services as experiences, performances, relationships, and systems that require different marketing logic than tangible goods.', 0),
  ('a063ca97-baaa-462f-bcdc-bc9a8e1e5f0e', 'd1e2f3a4-5b6c-4d81-8e82-9f0a1b2c3d41', 'cd6b658e-543a-425b-b31b-279074ea005e', 'subtopic'::public.curated_course_node_type, 'Why Services Need Distinct Marketing', 'Services are often bought before they can be fully evaluated, which makes trust, evidence, relationships, and experience design central.', 0),
