  ('91a30852-716b-4ca7-9b86-7178a60c03aa', 'd1e2f3a4-5b6c-4d81-8e82-9f0a1b2c3d41', 'e740ce3e-f376-4373-88ad-f84bd1c2d89b', 'concept'::public.curated_course_node_type, 'Concept testing, usability testing, and experience labs', null, 1),
  ('ed207c75-b5ca-49a3-a2fb-7254f530edae', 'd1e2f3a4-5b6c-4d81-8e82-9f0a1b2c3d41', 'e740ce3e-f376-4373-88ad-f84bd1c2d89b', 'concept'::public.curated_course_node_type, 'Iteration from insight to operating model', null, 2),
  ('594c3953-c805-496e-a04e-3513b10a91e7', 'd1e2f3a4-5b6c-4d81-8e82-9f0a1b2c3d41', null, 'topic'::public.curated_course_node_type, 'Service Encounters, People, Culture, and Internal Marketing', 'Study frontline employees, service culture, emotional labor, empowerment, and internal alignment as part of the marketing system.', 5),
  ('b87f2bac-de02-4d5f-94e8-592cc453c68c', 'd1e2f3a4-5b6c-4d81-8e82-9f0a1b2c3d41', '594c3953-c805-496e-a04e-3513b10a91e7', 'subtopic'::public.curated_course_node_type, 'Frontline Service Encounters', 'The service encounter is where brand promises become real for customers.', 0),
  ('c8405d2c-cf93-467b-a088-5159d0c12948', 'd1e2f3a4-5b6c-4d81-8e82-9f0a1b2c3d41', 'b87f2bac-de02-4d5f-94e8-592cc453c68c', 'concept'::public.curated_course_node_type, 'Moments of truth, service scripts, empathy, responsiveness, problem solving, and rapport', null, 0),
  ('81956b9f-6d54-49be-93e9-8b52d43726d3', 'd1e2f3a4-5b6c-4d81-8e82-9f0a1b2c3d41', 'b87f2bac-de02-4d5f-94e8-592cc453c68c', 'concept'::public.curated_course_node_type, 'Customer-contact employees and boundary-spanning roles', null, 1),
  ('63dd13d9-385f-4d72-a4db-cda67b344dec', 'd1e2f3a4-5b6c-4d81-8e82-9f0a1b2c3d41', 'b87f2bac-de02-4d5f-94e8-592cc453c68c', 'concept'::public.curated_course_node_type, 'Consistency without robotic delivery', null, 2),
  ('7fbd80e9-2f63-4856-8769-5f648c8eae4f', 'd1e2f3a4-5b6c-4d81-8e82-9f0a1b2c3d41', '594c3953-c805-496e-a04e-3513b10a91e7', 'subtopic'::public.curated_course_node_type, 'Service Culture and Internal Marketing', 'Employees deliver better service when the organization markets the promise internally as well as externally.', 1),
  ('7372add1-afd6-48f1-8c7e-19ea207c3819', 'd1e2f3a4-5b6c-4d81-8e82-9f0a1b2c3d41', '7fbd80e9-2f63-4856-8769-5f648c8eae4f', 'concept'::public.curated_course_node_type, 'Internal marketing, employer brand, service vision, training, communication, and recognition', null, 0),
  ('ae0c321b-6b62-4924-af76-21e1dde91359', 'd1e2f3a4-5b6c-4d81-8e82-9f0a1b2c3d41', '7fbd80e9-2f63-4856-8769-5f648c8eae4f', 'concept'::public.curated_course_node_type, 'Empowerment, psychological safety, leadership, and role clarity', null, 1),
  ('4af1d0c1-5de5-4ba4-b4c7-0deac6f87dd7', 'd1e2f3a4-5b6c-4d81-8e82-9f0a1b2c3d41', '7fbd80e9-2f63-4856-8769-5f648c8eae4f', 'concept'::public.curated_course_node_type, 'Aligning incentives with customer experience', null, 2),
  ('158a01a9-a168-4a71-aedf-dd792558b80a', 'd1e2f3a4-5b6c-4d81-8e82-9f0a1b2c3d41', '594c3953-c805-496e-a04e-3513b10a91e7', 'subtopic'::public.curated_course_node_type, 'Emotional Labor and Employee Experience', 'World-class service requires caring for the people who perform care, expertise, hospitality, or support.', 2),
  ('f9b215a8-4fe1-4136-85eb-771c12cafdf0', 'd1e2f3a4-5b6c-4d81-8e82-9f0a1b2c3d41', '158a01a9-a168-4a71-aedf-dd792558b80a', 'concept'::public.curated_course_node_type, 'Emotional labor, burnout, conflict, difficult customers, and service climate', null, 0),
  ('ecfacd89-1f55-459c-8e6d-13ed2eeab0f3', 'd1e2f3a4-5b6c-4d81-8e82-9f0a1b2c3d41', '158a01a9-a168-4a71-aedf-dd792558b80a', 'concept'::public.curated_course_node_type, 'Employee experience, engagement, staffing, and retention', null, 1),
  ('5f70f6d3-4f12-49b6-afcc-e8bde5e9d5f1', 'd1e2f3a4-5b6c-4d81-8e82-9f0a1b2c3d41', '158a01a9-a168-4a71-aedf-dd792558b80a', 'concept'::public.curated_course_node_type, 'Linking EX, CX, productivity, and service quality', null, 2),
  ('621db7fd-5602-440e-9334-3d1923229da0', 'd1e2f3a4-5b6c-4d81-8e82-9f0a1b2c3d41', null, 'topic'::public.curated_course_node_type, 'Physical Evidence, Servicescapes, Atmospherics, and Digital Interfaces', 'Examine how tangible cues, spaces, interfaces, and sensory evidence make intangible services understandable and trustworthy.', 6),
  ('a242f18b-e2df-4f01-bdbf-583f177310d5', 'd1e2f3a4-5b6c-4d81-8e82-9f0a1b2c3d41', '621db7fd-5602-440e-9334-3d1923229da0', 'subtopic'::public.curated_course_node_type, 'Physical Evidence and Tangible Cues', 'Customers use tangible signals to judge intangible services before and during consumption.', 0);
