  ('3c835179-27db-459a-9b5e-9175bffc6013', 'd1e2f3a4-5b6c-4d81-8e82-9f0a1b2c3d41', '178f1030-ab48-4a90-9bf8-d23ec72fe59f', 'concept'::public.curated_course_node_type, 'Ambient conditions, layout, spatial flow, symbols, artifacts, scent, lighting, sound, and crowding', null, 0),
