  ('7478ff86-ef3d-42cc-a97f-b54b6c57399c', 'd1e2f3a4-5b6c-4d81-8e82-9f0a1b2c3d41', 'eccbc21f-703d-4dcd-8ae2-5825486cd2b4', 'concept'::public.curated_course_node_type, 'UX, usability, information architecture, microcopy, onboarding, and error states', null, 0),
  ('22ebcd19-3b5d-43c4-9f34-2c7a9da94329', 'd1e2f3a4-5b6c-4d81-8e82-9f0a1b2c3d41', 'eccbc21f-703d-4dcd-8ae2-5825486cd2b4', 'concept'::public.curated_course_node_type, 'Self-service portals, mobile apps, chatbots, and omnichannel consistency', null, 1),
