  ('108a4ca9-071b-4569-bef1-90cbdcf0efa6', 'd1e2f3a4-5b6c-4d81-8e82-9f0a1b2c3d41', null, 'topic'::public.curated_course_node_type, 'Service Recovery, Complaint Management, and Customer Trust', 'Learn how firms respond to failure, rebuild trust, and turn breakdowns into learning and loyalty opportunities.', 7),
  ('31237cd4-dc86-4651-8906-fd2b8283cc21', 'd1e2f3a4-5b6c-4d81-8e82-9f0a1b2c3d41', '108a4ca9-071b-4569-bef1-90cbdcf0efa6', 'subtopic'::public.curated_course_node_type, 'Service Failure Types', 'Different failures require different recovery strategies and communication.', 0),
  ('4e1bf243-bc69-41db-8d9f-54bfdc970649', 'd1e2f3a4-5b6c-4d81-8e82-9f0a1b2c3d41', '31237cd4-dc86-4651-8906-fd2b8283cc21', 'concept'::public.curated_course_node_type, 'Core service failure, process failure, interaction failure, policy failure, and outcome failure', null, 0),
  ('6fc61209-331a-43bd-88a2-dde5c66939cc', 'd1e2f3a4-5b6c-4d81-8e82-9f0a1b2c3d41', '31237cd4-dc86-4651-8906-fd2b8283cc21', 'concept'::public.curated_course_node_type, 'Severity, controllability, recurrence, and customer vulnerability', null, 1),
  ('133a0e64-6686-4193-bca5-80855f2a69bb', 'd1e2f3a4-5b6c-4d81-8e82-9f0a1b2c3d41', '31237cd4-dc86-4651-8906-fd2b8283cc21', 'concept'::public.curated_course_node_type, 'Detecting failures before complaints appear', null, 2),
  ('b26d4339-c9be-46b2-aa83-aa1f8d988bda', 'd1e2f3a4-5b6c-4d81-8e82-9f0a1b2c3d41', '108a4ca9-071b-4569-bef1-90cbdcf0efa6', 'subtopic'::public.curated_course_node_type, 'Recovery Strategy', 'Recovery restores fairness, confidence, and relationship value after a breakdown.', 1),
  ('7c4a076a-260a-4173-afb1-3074e2e4c803', 'd1e2f3a4-5b6c-4d81-8e82-9f0a1b2c3d41', 'b26d4339-c9be-46b2-aa83-aa1f8d988bda', 'concept'::public.curated_course_node_type, 'Apology, explanation, speed, empathy, compensation, correction, and follow-up', null, 0),
  ('98b03b46-a661-42c1-8a11-f97cc10d9ed3', 'd1e2f3a4-5b6c-4d81-8e82-9f0a1b2c3d41', 'b26d4339-c9be-46b2-aa83-aa1f8d988bda', 'concept'::public.curated_course_node_type, 'Procedural, interactional, and distributive justice', null, 1),
  ('71150cfc-036c-44fd-9a9c-bf54791c57db', 'd1e2f3a4-5b6c-4d81-8e82-9f0a1b2c3d41', 'b26d4339-c9be-46b2-aa83-aa1f8d988bda', 'concept'::public.curated_course_node_type, 'Service guarantees and recovery empowerment', null, 2),
  ('3f25039e-41a1-4c25-9f1d-2038b8206c83', 'd1e2f3a4-5b6c-4d81-8e82-9f0a1b2c3d41', '108a4ca9-071b-4569-bef1-90cbdcf0efa6', 'subtopic'::public.curated_course_node_type, 'Complaint Learning and Trust Repair', 'Complaints are not only costs; they are high-value data about system weakness.', 2),
  ('5b825420-87ca-4ae3-9cb2-f7f1f495865a', 'd1e2f3a4-5b6c-4d81-8e82-9f0a1b2c3d41', '3f25039e-41a1-4c25-9f1d-2038b8206c83', 'concept'::public.curated_course_node_type, 'Complaint channels, escalation, root-cause analysis, closed-loop learning, and prevention', null, 0),
  ('bb9a38b5-7caf-431f-87eb-5e6cc946f112', 'd1e2f3a4-5b6c-4d81-8e82-9f0a1b2c3d41', '3f25039e-41a1-4c25-9f1d-2038b8206c83', 'concept'::public.curated_course_node_type, 'Trust, forgiveness, switching, negative word of mouth, and recovery paradox', null, 1),
  ('9d02edcb-6b42-45d9-a56f-be6ef2cb2b4c', 'd1e2f3a4-5b6c-4d81-8e82-9f0a1b2c3d41', '3f25039e-41a1-4c25-9f1d-2038b8206c83', 'concept'::public.curated_course_node_type, 'When recovery can and cannot create loyalty', null, 2),
  ('0f5b6177-b38f-49bc-91cf-11baeb1a5580', 'd1e2f3a4-5b6c-4d81-8e82-9f0a1b2c3d41', null, 'topic'::public.curated_course_node_type, 'Service Pricing, Revenue Management, and Value Communication', 'Apply pricing logic to intangible, time-sensitive, capacity-constrained, and relationship-based services.', 8),
  ('ef2c7213-1c22-4316-a347-cc75257cafec', 'd1e2f3a4-5b6c-4d81-8e82-9f0a1b2c3d41', '0f5b6177-b38f-49bc-91cf-11baeb1a5580', 'subtopic'::public.curated_course_node_type, 'Pricing Intangible Value', 'Service pricing must communicate value for outcomes that may be uncertain, delayed, or co-produced.', 0),
