  ('699589db-0cac-42d7-86f9-57c62d731250', 'd1e2f3a4-5b6c-4d81-8e82-9f0a1b2c3d41', 'ef2c7213-1c22-4316-a347-cc75257cafec', 'concept'::public.curated_course_node_type, 'Hourly, subscription, retainer, freemium, usage-based, and bundled pricing', null, 1),
  ('e6d560ce-c819-47ea-bc5f-34111f1f87b0', 'd1e2f3a4-5b6c-4d81-8e82-9f0a1b2c3d41', 'ef2c7213-1c22-4316-a347-cc75257cafec', 'concept'::public.curated_course_node_type, 'Communicating expertise, convenience, reliability, and peace of mind', null, 2),
  ('d51fc4de-773a-4ee5-9325-a13d16c67e78', 'd1e2f3a4-5b6c-4d81-8e82-9f0a1b2c3d41', '0f5b6177-b38f-49bc-91cf-11baeb1a5580', 'subtopic'::public.curated_course_node_type, 'Revenue and Yield Management', 'Capacity-constrained services often need dynamic pricing to balance demand and profitability.', 1),
  ('92c556e2-efcb-4d39-9055-064ed59e5249', 'd1e2f3a4-5b6c-4d81-8e82-9f0a1b2c3d41', 'd51fc4de-773a-4ee5-9325-a13d16c67e78', 'concept'::public.curated_course_node_type, 'Yield management, revenue management, dynamic pricing, peak/off-peak pricing, and load factors', null, 0),
  ('9e219d38-89db-478d-99d4-4c0fd92a7339', 'd1e2f3a4-5b6c-4d81-8e82-9f0a1b2c3d41', 'd51fc4de-773a-4ee5-9325-a13d16c67e78', 'concept'::public.curated_course_node_type, 'Hotels, airlines, restaurants, events, ride-share, and appointment services', null, 1),
  ('588d26a8-1000-4570-a9d4-2d7bfcf2524a', 'd1e2f3a4-5b6c-4d81-8e82-9f0a1b2c3d41', 'd51fc4de-773a-4ee5-9325-a13d16c67e78', 'concept'::public.curated_course_node_type, 'Fairness perceptions and transparency', null, 2),
  ('759d0825-9e49-41eb-abb6-e1b6f3ef3713', 'd1e2f3a4-5b6c-4d81-8e82-9f0a1b2c3d41', '0f5b6177-b38f-49bc-91cf-11baeb1a5580', 'subtopic'::public.curated_course_node_type, 'Price Fairness and Behavioral Response', 'Customers react not only to price level but also to the perceived fairness of rules and fees.', 2),
  ('6c5606a1-9b56-477f-b851-ad4a88700b56', 'd1e2f3a4-5b6c-4d81-8e82-9f0a1b2c3d41', '759d0825-9e49-41eb-abb6-e1b6f3ef3713', 'concept'::public.curated_course_node_type, 'Reference price, fairness, partitioned pricing, fees, discounts, tipping, and subscriptions', null, 0),
  ('69328e14-5426-4205-86ab-e5d499acc12b', 'd1e2f3a4-5b6c-4d81-8e82-9f0a1b2c3d41', '759d0825-9e49-41eb-abb6-e1b6f3ef3713', 'concept'::public.curated_course_node_type, 'Willingness to pay, price sensitivity, and perceived sacrifice', null, 1),
  ('5c42b4f9-2ae6-4ec6-9a55-679eaa6596c7', 'd1e2f3a4-5b6c-4d81-8e82-9f0a1b2c3d41', '759d0825-9e49-41eb-abb6-e1b6f3ef3713', 'concept'::public.curated_course_node_type, 'Avoiding hidden-fee backlash and trust erosion', null, 2),
  ('8228cfc2-a3aa-4a61-bcba-f82e19db8763', 'd1e2f3a4-5b6c-4d81-8e82-9f0a1b2c3d41', null, 'topic'::public.curated_course_node_type, 'Demand, Capacity, Queues, and Wait-Time Experience Design', 'Manage demand and capacity while designing fair, transparent, and emotionally intelligent waiting experiences.', 9),
